type originalHostCategoryTemplate struct {
	Domain   string         `json:"source_db_domain"`
	Schema   string         `json:"schema"`
	URL      string         `json:"domain"`
	Aliases  []string       `json:"ext_domains"`
	Category map[string]any `json:"category"`
}

var originalHostCategoryTemplates = func() map[string]originalHostCategoryTemplate {
	var rows []originalHostCategoryTemplate
	d := json.NewDecoder(bytes.NewBufferString(originalHostCategoryData))
	d.UseNumber()
	if d.Decode(&rows) != nil {
		panic("invalid frozen host category data")
	}
	out := map[string]originalHostCategoryTemplate{}
	for _, row := range rows {
		for _, value := range append([]string{row.Domain, row.URL}, row.Aliases...) {
			key := value
			if strings.HasPrefix(value, "http") {
				u, err := url.Parse(value)
				if err != nil {
					continue
				}
				key = u.Hostname()
			}
			out[sourceindexer.Domain(key)] = row
		}
	}
	return out
}()

func originalHostCategoryForSite(site SiteConfig) (originalHostCategoryTemplate, bool) {
	if row, ok := originalHostCategoryTemplates[sourceindexer.Domain(site.Domain)]; ok {
		return row, true
	}
	u, err := url.Parse(site.BaseURL)
	if err != nil {
		return originalHostCategoryTemplate{}, false
	}
	row, ok := originalHostCategoryTemplates[sourceindexer.Domain(u.Hostname())]
	return row, ok
}

// Fixed generic Spider.__get_search_url category block. IDs retain their
// source numeric/string type: field concatenation must not coerce a source
// TypeError into a fabricated request. The caller owns the core base params.
func originalHostApplyCategory(params map[string]any, category map[string]any, selection *string) error {
	if len(category) == 0 {
		return nil
	}
	var allowed map[string]bool
	if selection != nil && *selection != "" {
		allowed = map[string]bool{}
		for _, id := range strings.Split(*selection, ",") {
			allowed[id] = true
		}
	}
	cats := []any{}
	for _, key := range []string{"movie", "tv"} {
		if !sourceSubscriptionTruth(category[key]) {
			continue
		}
		if rows, ok := category[key].([]any); ok {
			cats = append(cats, rows...)
		} else if category[key] != nil {
			return errors.New("invalid source category rows")
		}
	}
	text := func(value any) (string, error) {
		switch value := value.(type) {
		case string:
			return value, nil
		case json.Number:
			return value.String(), nil
		case nil:
			return "None", nil
		case bool:
			if value {
				return "True", nil
			}
			return "False", nil
		}
		return "", errors.New("invalid source category ID")
	}
	for _, value := range cats {
		row, ok := value.(map[string]any)
		if !ok {
			return errors.New("invalid source category row")
		}
		id, err := text(row["id"])
		if err != nil {
			return err
		}
		if allowed != nil && !allowed[id] {
			continue
		}
		field, hasField := category["field"].(string)
		if sourceSubscriptionTruth(category["field"]) {
			if !hasField {
				return errors.New("invalid source category field")
			}
			var old any = ""
			if value, ok := params[field]; ok {
				old = value
			}
			prefix, ok := old.(string)
			if !ok {
				return errors.New("source category field is not a string")
			}
			var delimiter any = " "
			if value, ok := category["delimiter"]; ok {
				delimiter = value
			}
			join, ok := delimiter.(string)
			if !ok {
				return errors.New("source category delimiter is not a string")
			}
			rawID, ok := row["id"].(string)
			if !ok {
				return errors.New("source category field ID is not a string")
			}
			params[field] = prefix + join + rawID
		} else {
			params["cat"+id] = 1
		}
	}
	return nil
}

func originalHostSiteCategoryParams(site SiteConfig, selection *string) (url.Values, error) {
	out := url.Values{}
	if site.Kind == "mteam" {
		return out, nil
	} // Fixed MTorrent.search has no cat argument.
	if site.Kind == "rousi" {
		if selection != nil && *selection != "" {
			names := map[string]string{"1": "movie", "2": "tv", "3": "documentary", "4": "animation", "6": "variety"}
			for _, id := range strings.Split(*selection, ",") {
				if name, ok := names[strings.TrimSpace(id)]; ok {
					out.Set("category", name)
					break
				}
			}
		}
		return out, nil
	}
	row, known := originalHostCategoryForSite(site)
	if !known {
		if selection != nil && *selection != "" {
			return nil, bad("SITE_CATEGORY_UNSUPPORTED", "该站点尚无已核实的原版分类定义")
		}
		return out, nil
	}
	params := map[string]any{}
	if err := originalHostApplyCategory(params, row.Category, selection); err != nil {
		return nil, bad("SITE_CATEGORY_INVALID", "原版站点分类定义无法生成请求")
	}
	for key, value := range params {
		switch value := value.(type) {
		case string:
			out.Set(key, value)
		case int:
			if value == 1 {
				out.Set(key, "1")
			} else {
				return nil, bad("SITE_CATEGORY_INVALID", "原版站点分类值无效")
			}
		default:
			return nil, bad("SITE_CATEGORY_INVALID", "原版站点分类值无效")
		}
	}
	return out, nil
}
